CREATE TABLE `estudiantes` (`id_estudiante` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL COMMENT 'Nombre completo', `correo` VARCHAR(160) NOT NULL, `ciudad` VARCHAR(90), `fecha_registro` DATE NOT NULL, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_estudiante`)) ENGINE=InnoDB COMMENT='Personas registradas';
CREATE TABLE `facultades` (`id_facultad` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(100) NOT NULL, `descripcion` VARCHAR(180), PRIMARY KEY (`id_facultad`)) ENGINE=InnoDB COMMENT='Clasificación de recursos';
CREATE TABLE `materias` (`id_materia` INT NOT NULL AUTO_INCREMENT, `id_facultad` INT NOT NULL, `nombre` VARCHAR(130) NOT NULL, `costo_matricula` DECIMAL(11,2) NOT NULL, `cupos` INT NOT NULL DEFAULT 0, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_materia`), KEY `idx_recurso_categoria` (`id_facultad`), CONSTRAINT `fk_recurso_categoria` FOREIGN KEY (`id_facultad`) REFERENCES `facultades` (`id_facultad`)) ENGINE=InnoDB COMMENT='Recursos o artículos del catálogo';
CREATE TABLE `campus` (`id_campus` INT NOT NULL AUTO_INCREMENT, `nombre` VARCHAR(110) NOT NULL, `ciudad` VARCHAR(90) NOT NULL, `fecha_apertura` DATE, PRIMARY KEY (`id_campus`)) ENGINE=InnoDB COMMENT='Ubicaciones operativas';
CREATE TABLE `docentes` (`id_docente` INT NOT NULL AUTO_INCREMENT, `id_campus` INT NOT NULL, `nombre` VARCHAR(110) NOT NULL, `salario` DECIMAL(11,2), `fecha_ingreso` DATE, `activo` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_docente`), KEY `idx_empleado_sede` (`id_campus`), CONSTRAINT `fk_empleado_sede` FOREIGN KEY (`id_campus`) REFERENCES `campus` (`id_campus`)) ENGINE=InnoDB COMMENT='Personal';
CREATE TABLE `matriculas` (`id_matricula` INT NOT NULL AUTO_INCREMENT, `id_estudiante` INT NOT NULL, `id_docente` INT NOT NULL, `id_campus` INT NOT NULL, `fecha` DATE NOT NULL, `estado` VARCHAR(25) NOT NULL, `total` DECIMAL(12,2) NOT NULL, `comentario` VARCHAR(180), PRIMARY KEY (`id_matricula`), KEY `idx_operacion_persona` (`id_estudiante`), KEY `idx_operacion_empleado` (`id_docente`), KEY `idx_operacion_sede` (`id_campus`), CONSTRAINT `fk_operacion_persona` FOREIGN KEY (`id_estudiante`) REFERENCES `estudiantes` (`id_estudiante`), CONSTRAINT `fk_operacion_empleado` FOREIGN KEY (`id_docente`) REFERENCES `docentes` (`id_docente`), CONSTRAINT `fk_operacion_sede` FOREIGN KEY (`id_campus`) REFERENCES `campus` (`id_campus`)) ENGINE=InnoDB COMMENT='Registro principal de operaciones';
CREATE TABLE `materias_matriculadas` (`id_materia_matriculada` INT NOT NULL AUTO_INCREMENT, `id_matricula` INT NOT NULL, `id_materia` INT NOT NULL, `cantidad` INT NOT NULL, `precio_unitario` DECIMAL(11,2) NOT NULL, `descuento` DECIMAL(10,2) NOT NULL DEFAULT 0, PRIMARY KEY (`id_materia_matriculada`), KEY `idx_detalle_operacion` (`id_matricula`), KEY `idx_detalle_recurso` (`id_materia`), CONSTRAINT `fk_detalle_operacion` FOREIGN KEY (`id_matricula`) REFERENCES `matriculas` (`id_matricula`), CONSTRAINT `fk_detalle_recurso` FOREIGN KEY (`id_materia`) REFERENCES `materias` (`id_materia`)) ENGINE=InnoDB COMMENT='Detalle de recursos por operación';
CREATE TABLE `pagos_matricula` (`id_pago_matricula` INT NOT NULL AUTO_INCREMENT, `id_matricula` INT NOT NULL, `fecha_pago` DATE NOT NULL, `monto` DECIMAL(12,2) NOT NULL, `metodo` VARCHAR(25) NOT NULL, `confirmado` TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (`id_pago_matricula`), KEY `idx_pago_operacion` (`id_matricula`), CONSTRAINT `fk_pago_operacion` FOREIGN KEY (`id_matricula`) REFERENCES `matriculas` (`id_matricula`)) ENGINE=InnoDB COMMENT='Movimientos de cobro';
CREATE TABLE `observaciones_academicas` (`id_observacion_academica` INT NOT NULL AUTO_INCREMENT, `id_matricula` INT NOT NULL, `fecha_evento` DATE NOT NULL, `tipo` VARCHAR(50) NOT NULL, `descripcion` VARCHAR(220), `puntuacion` INT, PRIMARY KEY (`id_observacion_academica`), KEY `idx_evento_operacion` (`id_matricula`), CONSTRAINT `fk_evento_operacion` FOREIGN KEY (`id_matricula`) REFERENCES `matriculas` (`id_matricula`)) ENGINE=InnoDB COMMENT='Eventos de seguimiento asociados a una operación';
